//! Verification report types for security checks.

use std::path::PathBuf;

use crate::closed_enum::closed_enum;
use crate::error::ArchiveError;
use crate::formats::detect::ArchiveType;
use crate::inspection::manifest::ArchiveEntry;
use crate::inspection::manifest::ArchiveManifest;

/// Result of archive verification.
///
/// Generated by `verify_archive()`, contains the result of the security checks
/// performed without extracting files to disk. Payload integrity is not
/// verified, so `integrity_status()` is always [`CheckStatus::Skipped`]. Fields
/// are private: the overall and security statuses are derived from the issue
/// list, so a report can never contradict its own issues.
///
/// # Examples
///
/// ```no_run
/// use exarch_core::SecurityConfig;
/// use exarch_core::VerificationStatus;
/// use exarch_core::verify_archive;
///
/// # fn main() -> Result<(), Box<dyn std::error::Error>> {
/// let config = SecurityConfig::default();
/// let report = verify_archive("archive.tar.gz", &config)?;
///
/// if report.status() == VerificationStatus::Pass {
///     println!("Archive is safe to extract");
/// } else {
///     eprintln!("Security issues found:");
///     for issue in report.issues() {
///         eprintln!("  [{}] {}", issue.severity, issue.message);
///     }
/// }
/// # Ok(())
/// # }
/// ```
#[derive(Debug, Clone)]
pub struct VerificationReport {
    issues: Vec<VerificationIssue>,
    integrity_status: CheckStatus,
    total_entries: usize,
    suspicious_entries: usize,
    total_size: u64,
    format: ArchiveType,
}

impl VerificationReport {
    /// Builds a report by running `issues_for` over every manifest entry.
    ///
    /// Totals and format come from the manifest. An entry counts as
    /// suspicious when it has at least one issue of [`IssueSeverity::Medium`]
    /// or higher, which makes `status() == Pass` equivalent to
    /// `suspicious_entries() == 0`. Issues are sorted from most to least
    /// severe.
    ///
    /// # Examples
    ///
    /// ```
    /// use std::path::PathBuf;
    ///
    /// use exarch_core::ArchiveEntry;
    /// use exarch_core::ArchiveManifest;
    /// use exarch_core::ManifestEntryKind;
    /// use exarch_core::VerificationReport;
    /// use exarch_core::VerificationStatus;
    /// use exarch_core::formats::detect::ArchiveType;
    ///
    /// let mut manifest = ArchiveManifest::new(ArchiveType::Tar);
    /// let entry = ArchiveEntry::new(PathBuf::from("a.txt"), ManifestEntryKind::File, 1);
    /// manifest.add_entry(entry)?;
    ///
    /// let report = VerificationReport::from_entry_issues(&manifest, |_| Vec::new());
    /// assert_eq!(report.status(), VerificationStatus::Pass);
    /// assert_eq!(report.total_entries(), 1);
    /// # Ok::<(), exarch_core::ArchiveError>(())
    /// ```
    #[must_use]
    pub fn from_entry_issues<F>(manifest: &ArchiveManifest, issues_for: F) -> Self
    where
        F: FnMut(&ArchiveEntry) -> Vec<VerificationIssue>,
    {
        let lists = manifest.entries().iter().map(issues_for).collect();
        Self::from_entry_issue_lists(manifest, lists)
    }

    /// Builds a report from one precomputed issue list per manifest entry.
    pub(crate) fn from_entry_issue_lists(
        manifest: &ArchiveManifest,
        lists: Vec<Vec<VerificationIssue>>,
    ) -> Self {
        let mut issues = Vec::new();
        let mut suspicious_entries = 0;

        for entry_issues in lists {
            if entry_issues
                .iter()
                .any(|i| i.severity >= IssueSeverity::Medium)
            {
                suspicious_entries += 1;
            }
            issues.extend(entry_issues);
        }

        issues.sort_by(|a, b| a.severity.cmp(&b.severity).reverse());

        Self {
            issues,
            // TODO(#623): replace Skipped with a bounded decode-to-EOF/CRC pass
            integrity_status: CheckStatus::Skipped,
            total_entries: manifest.total_entries(),
            suspicious_entries,
            total_size: manifest.total_size(),
            format: manifest.format(),
        }
    }

    /// Returns the overall status, derived from the issue severities.
    #[must_use]
    pub fn status(&self) -> VerificationStatus {
        determine_status(&self.issues)
    }

    /// Returns the security check result, derived from security-category
    /// issues.
    #[must_use]
    pub fn security_status(&self) -> CheckStatus {
        determine_security_status(&self.issues)
    }

    /// Returns the integrity check result.
    #[must_use]
    pub const fn integrity_status(&self) -> CheckStatus {
        self.integrity_status
    }

    /// Returns all issues found, sorted from most to least severe.
    #[must_use]
    pub fn issues(&self) -> &[VerificationIssue] {
        &self.issues
    }

    /// Consumes the report and returns its issues.
    #[must_use]
    pub fn into_issues(self) -> Vec<VerificationIssue> {
        self.issues
    }

    /// Returns the total number of entries scanned.
    #[must_use]
    pub const fn total_entries(&self) -> usize {
        self.total_entries
    }

    /// Returns the number of entries with a Medium-or-higher issue.
    #[must_use]
    pub const fn suspicious_entries(&self) -> usize {
        self.suspicious_entries
    }

    /// Returns the total uncompressed size in bytes.
    #[must_use]
    pub const fn total_size(&self) -> u64 {
        self.total_size
    }

    /// Returns the archive format.
    #[must_use]
    pub const fn format(&self) -> ArchiveType {
        self.format
    }

    /// Returns true if the archive is safe (no Medium-or-higher severity
    /// issues).
    #[must_use]
    pub fn is_safe(&self) -> bool {
        self.status() == VerificationStatus::Pass
    }

    /// Returns true if there are any critical severity issues.
    #[must_use]
    pub fn has_critical_issues(&self) -> bool {
        self.issues
            .iter()
            .any(|i| i.severity == IssueSeverity::Critical)
    }

    /// Returns issues of a specific severity level.
    #[must_use]
    pub fn issues_by_severity(&self, severity: IssueSeverity) -> Vec<&VerificationIssue> {
        self.issues
            .iter()
            .filter(|i| i.severity == severity)
            .collect()
    }
}

fn determine_status(issues: &[VerificationIssue]) -> VerificationStatus {
    let has_critical = issues.iter().any(|i| i.severity == IssueSeverity::Critical);
    let has_high = issues.iter().any(|i| i.severity == IssueSeverity::High);
    let has_medium = issues.iter().any(|i| i.severity == IssueSeverity::Medium);

    if has_critical || has_high {
        VerificationStatus::Fail
    } else if has_medium {
        VerificationStatus::Warning
    } else {
        VerificationStatus::Pass
    }
}

fn determine_security_status(issues: &[VerificationIssue]) -> CheckStatus {
    let mut security_issues = issues
        .iter()
        .filter(|i| i.category.is_security())
        .peekable();

    if security_issues.peek().is_none() {
        return CheckStatus::Pass;
    }

    let fails = security_issues
        .any(|i| i.severity == IssueSeverity::Critical || i.severity == IssueSeverity::High);

    if fails {
        CheckStatus::Fail
    } else {
        CheckStatus::Warning
    }
}

closed_enum! {
    /// Overall verification status.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum VerificationStatus {
        /// All checks passed
        Pass => "PASS",

        /// One or more checks failed
        Fail => "FAIL",

        /// Checks completed with warnings
        Warning => "WARNING",
    }
}

closed_enum! {
    /// Status of a specific check category.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum CheckStatus {
        /// Check passed
        Pass => "OK",

        /// Check failed
        Fail => "FAILED",

        /// Check completed with warnings
        Warning => "WARNING",

        /// Check was skipped
        Skipped => "SKIPPED",
    }
}

/// Single verification issue.
///
/// Construct with [`VerificationIssue::new`] or
/// [`VerificationIssue::from_error`].
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct VerificationIssue {
    /// Issue severity level
    pub severity: IssueSeverity,

    /// Issue category
    pub category: IssueCategory,

    /// Entry path that triggered issue (if applicable)
    pub entry_path: Option<PathBuf>,

    /// Human-readable description
    pub message: String,

    /// Optional context (compression ratio, target path, etc.)
    pub context: Option<String>,
}

impl VerificationIssue {
    /// Creates an issue with no entry path or context attached.
    #[must_use]
    pub const fn new(severity: IssueSeverity, category: IssueCategory, message: String) -> Self {
        Self {
            severity,
            category,
            entry_path: None,
            message,
            context: None,
        }
    }

    /// Creates a verification issue from an extraction error.
    #[must_use]
    pub fn from_error(error: &ArchiveError, entry_path: Option<PathBuf>) -> Self {
        let (severity, category, message) = match error {
            ArchiveError::PathTraversal { path } => (
                IssueSeverity::Critical,
                IssueCategory::PathTraversal,
                format!("Path traversal detected: {}", path.display()),
            ),
            ArchiveError::SymlinkEscape { path } => (
                IssueSeverity::Critical,
                IssueCategory::SymlinkEscape,
                format!("Symlink escape: {}", path.display()),
            ),
            ArchiveError::HardlinkEscape { path } => (
                IssueSeverity::Critical,
                IssueCategory::HardlinkEscape,
                format!("Hardlink escape: {}", path.display()),
            ),
            ArchiveError::ZipBomb(details) => (
                IssueSeverity::Critical,
                IssueCategory::ZipBomb,
                format!("Potential zip bomb: {details}"),
            ),
            ArchiveError::QuotaExceeded { resource } => (
                IssueSeverity::High,
                IssueCategory::QuotaExceeded,
                resource.to_string(),
            ),
            ArchiveError::InvalidPermissions { path, mode } => (
                IssueSeverity::Medium,
                IssueCategory::InvalidPermissions,
                format!(
                    "Invalid permissions: {} (mode: {:#o})",
                    path.display(),
                    mode
                ),
            ),
            ArchiveError::Io(io_err) => (
                IssueSeverity::High,
                IssueCategory::InvalidArchive,
                format!("I/O error: {io_err}"),
            ),
            ArchiveError::InvalidArchive(msg) => (
                IssueSeverity::High,
                IssueCategory::InvalidArchive,
                format!("Invalid archive: {msg}"),
            ),
            ArchiveError::SecurityViolation { reason } => (
                IssueSeverity::High,
                IssueCategory::SecurityPolicy,
                format!("Security violation: {reason}"),
            ),
            ArchiveError::SourceNotFound { path } => (
                IssueSeverity::High,
                IssueCategory::InvalidArchive,
                format!("Source not found: {}", path.display()),
            ),
            ArchiveError::SourceNotAccessible { path } => (
                IssueSeverity::High,
                IssueCategory::InvalidArchive,
                format!("Source not accessible: {}", path.display()),
            ),
            ArchiveError::OutputExists { path } => (
                IssueSeverity::Medium,
                IssueCategory::InvalidArchive,
                format!("Output already exists: {}", path.display()),
            ),
            ArchiveError::InvalidCompressionLevel { level } => (
                IssueSeverity::Medium,
                IssueCategory::InvalidArchive,
                format!("Invalid compression level: {level}"),
            ),
            ArchiveError::UnknownFormat { path } => (
                IssueSeverity::High,
                IssueCategory::InvalidArchive,
                format!("Unknown format: {}", path.display()),
            ),
            ArchiveError::InvalidConfiguration { reason } => (
                IssueSeverity::High,
                IssueCategory::InvalidArchive,
                format!("Invalid configuration: {reason}"),
            ),
            ArchiveError::PartialExtraction { source, .. } => {
                return Self::from_error(source, entry_path);
            }
        };

        Self {
            severity,
            category,
            entry_path,
            message,
            context: None,
        }
    }
}

closed_enum! {
    /// Issue severity levels (ordered from least to most severe for Ord).
    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
    pub enum IssueSeverity {
        /// Informational
        Info => "INFO",

        /// Policy violation
        Low => "LOW",

        /// Security concern
        Medium => "MEDIUM",

        /// Exploitable security issue
        High => "HIGH",

        /// CVE-level vulnerability
        Critical => "CRITICAL",
    }
}

closed_enum! {
    /// Issue categories (maps to security checks).
    ///
    /// `#[non_exhaustive]` so a future security check is not a breaking change
    /// for downstream matches.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    #[non_exhaustive]
    pub enum IssueCategory {
        /// Path traversal attack
        PathTraversal => "Path Traversal",

        /// Symlink escape attack
        SymlinkEscape => "Symlink Escape",

        /// Hardlink escape attack
        HardlinkEscape => "Hardlink Escape",

        /// Zip bomb (excessive compression)
        ZipBomb => "Zip Bomb",

        /// Invalid or unsafe permissions
        InvalidPermissions => "Invalid Permissions",

        /// Quota exceeded (file count or size)
        QuotaExceeded => "Quota Exceeded",

        /// Entry rejected by the security policy (links disallowed, NUL bytes,
        /// banned component, ...)
        SecurityPolicy => "Security Policy",

        /// Invalid or corrupted archive
        InvalidArchive => "Invalid Archive",

        /// Suspicious path or filename
        SuspiciousPath => "Suspicious Path",

        /// Executable file detected
        ExecutableFile => "Executable File",
    }
}

impl IssueCategory {
    /// Whether issues of this category come from a security check, and so
    /// count towards [`VerificationReport::security_status`].
    ///
    /// The match is exhaustive on purpose: a new category must be classified.
    #[must_use]
    pub const fn is_security(self) -> bool {
        match self {
            Self::PathTraversal
            | Self::SymlinkEscape
            | Self::HardlinkEscape
            | Self::ZipBomb
            | Self::InvalidPermissions
            | Self::QuotaExceeded
            | Self::SecurityPolicy => true,
            Self::InvalidArchive | Self::SuspiciousPath | Self::ExecutableFile => false,
        }
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;
    use crate::ZipBombDetails;
    use crate::ZipBombScope;
    use std::io;

    use crate::inspection::manifest::ManifestEntryKind;

    fn spellings<T: Copy>(all: &[T], text: impl Fn(T) -> &'static str) -> Vec<&'static str> {
        all.iter().map(|v| text(*v)).collect()
    }

    #[test]
    fn test_enum_as_str_spellings_and_display() {
        assert_eq!(
            spellings(VerificationStatus::ALL, VerificationStatus::as_str),
            ["PASS", "FAIL", "WARNING"]
        );
        assert_eq!(
            spellings(CheckStatus::ALL, CheckStatus::as_str),
            ["OK", "FAILED", "WARNING", "SKIPPED"]
        );
        assert_eq!(
            spellings(IssueSeverity::ALL, IssueSeverity::as_str),
            ["INFO", "LOW", "MEDIUM", "HIGH", "CRITICAL"]
        );
        assert_eq!(
            spellings(IssueCategory::ALL, IssueCategory::as_str),
            [
                "Path Traversal",
                "Symlink Escape",
                "Hardlink Escape",
                "Zip Bomb",
                "Invalid Permissions",
                "Quota Exceeded",
                "Security Policy",
                "Invalid Archive",
                "Suspicious Path",
                "Executable File",
            ]
        );
        for category in IssueCategory::ALL {
            assert_eq!(category.to_string(), category.as_str());
        }
        for severity in IssueSeverity::ALL {
            assert_eq!(severity.to_string(), severity.as_str());
        }
    }

    #[test]
    fn test_severity_all_is_ascending() {
        assert!(IssueSeverity::ALL.is_sorted());
    }

    #[test]
    fn test_determine_status_pass() {
        let issues = vec![];
        assert_eq!(determine_status(&issues), VerificationStatus::Pass);
    }

    #[test]
    fn test_determine_status_fail_critical() {
        let issues = vec![VerificationIssue {
            severity: IssueSeverity::Critical,
            category: IssueCategory::PathTraversal,
            entry_path: None,
            message: "Test".to_string(),
            context: None,
        }];
        assert_eq!(determine_status(&issues), VerificationStatus::Fail);
    }

    #[test]
    fn test_determine_status_fail_high() {
        let issues = vec![VerificationIssue {
            severity: IssueSeverity::High,
            category: IssueCategory::QuotaExceeded,
            entry_path: None,
            message: "Test".to_string(),
            context: None,
        }];
        assert_eq!(determine_status(&issues), VerificationStatus::Fail);
    }

    #[test]
    fn test_determine_status_warning() {
        let issues = vec![VerificationIssue {
            severity: IssueSeverity::Medium,
            category: IssueCategory::InvalidPermissions,
            entry_path: None,
            message: "Test".to_string(),
            context: None,
        }];
        assert_eq!(determine_status(&issues), VerificationStatus::Warning);
    }

    #[test]
    fn test_verification_issue_from_path_traversal() {
        let error = ArchiveError::PathTraversal {
            path: PathBuf::from("../../etc/passwd"),
        };
        let issue = VerificationIssue::from_error(&error, None);

        assert_eq!(issue.severity, IssueSeverity::Critical);
        assert_eq!(issue.category, IssueCategory::PathTraversal);
        assert!(issue.message.contains("Path traversal"));
    }

    #[test]
    fn test_verification_issue_from_symlink_escape() {
        let error = ArchiveError::SymlinkEscape {
            path: PathBuf::from("link"),
        };
        let issue = VerificationIssue::from_error(&error, Some(PathBuf::from("link")));

        assert_eq!(issue.severity, IssueSeverity::Critical);
        assert_eq!(issue.category, IssueCategory::SymlinkEscape);
        assert!(issue.message.contains("Symlink escape"));
    }

    #[test]
    fn test_verification_issue_from_zip_bomb() {
        let error =
            ArchiveError::ZipBomb(ZipBombDetails::new(ZipBombScope::Entry, 1000, 1_000_000));
        let issue = VerificationIssue::from_error(&error, None);

        assert_eq!(issue.severity, IssueSeverity::Critical);
        assert_eq!(issue.category, IssueCategory::ZipBomb);
        assert!(issue.message.contains("zip bomb"));
    }

    #[test]
    fn test_verification_issue_from_io_error() {
        let error = ArchiveError::Io(io::Error::new(io::ErrorKind::NotFound, "not found"));
        let issue = VerificationIssue::from_error(&error, None);

        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
    }

    fn issue(severity: IssueSeverity, category: IssueCategory) -> VerificationIssue {
        VerificationIssue::new(severity, category, "Test".to_string())
    }

    fn report_with(issues: Vec<VerificationIssue>) -> VerificationReport {
        let mut manifest = ArchiveManifest::new(ArchiveType::TarGz);
        let entry = ArchiveEntry::new(PathBuf::from("a"), ManifestEntryKind::File, 1024);
        manifest.add_entry(entry).unwrap();
        let mut issues = Some(issues);
        VerificationReport::from_entry_issues(&manifest, |_| issues.take().unwrap_or_default())
    }

    #[test]
    fn test_verification_report_is_safe() {
        let report = report_with(Vec::new());

        assert!(report.is_safe());
        assert_eq!(report.total_entries(), 1);
        assert_eq!(report.total_size(), 1024);
        assert_eq!(report.format(), ArchiveType::TarGz);
        assert_eq!(report.suspicious_entries(), 0);
    }

    #[test]
    fn test_verification_report_not_safe() {
        let report = report_with(vec![issue(
            IssueSeverity::Critical,
            IssueCategory::PathTraversal,
        )]);

        assert!(!report.is_safe());
        assert!(report.has_critical_issues());
        assert_eq!(report.status(), VerificationStatus::Fail);
        assert_eq!(report.security_status(), CheckStatus::Fail);
        assert_eq!(report.suspicious_entries(), 1);
    }

    #[test]
    fn test_status_pass_iff_no_suspicious_entries() {
        for severity in IssueSeverity::ALL {
            let report = report_with(vec![issue(*severity, IssueCategory::SuspiciousPath)]);
            assert_eq!(
                report.status() == VerificationStatus::Pass,
                report.suspicious_entries() == 0,
                "{severity}"
            );
        }
    }

    #[test]
    fn test_issues_sorted_most_severe_first() {
        let report = report_with(vec![
            issue(IssueSeverity::Low, IssueCategory::ExecutableFile),
            issue(IssueSeverity::Critical, IssueCategory::PathTraversal),
            issue(IssueSeverity::Medium, IssueCategory::InvalidPermissions),
        ]);
        let severities: Vec<_> = report.issues().iter().map(|i| i.severity).collect();
        assert_eq!(
            severities,
            [
                IssueSeverity::Critical,
                IssueSeverity::Medium,
                IssueSeverity::Low
            ]
        );
    }

    #[test]
    fn test_verification_issue_from_hardlink_escape() {
        let error = ArchiveError::HardlinkEscape {
            path: PathBuf::from("link"),
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::Critical);
        assert_eq!(issue.category, IssueCategory::HardlinkEscape);
        assert!(issue.message.contains("Hardlink escape"));
    }

    #[test]
    fn test_verification_issue_from_quota_exceeded() {
        let error = ArchiveError::QuotaExceeded {
            resource: crate::error::QuotaResource::FileCount {
                current: 11,
                max: 10,
            },
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::QuotaExceeded);
    }

    #[test]
    fn test_verification_issue_from_invalid_permissions() {
        let error = ArchiveError::InvalidPermissions {
            path: PathBuf::from("file.txt"),
            mode: 0o777,
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::Medium);
        assert_eq!(issue.category, IssueCategory::InvalidPermissions);
        assert!(issue.message.contains("Invalid permissions"));
    }

    #[test]
    fn test_verification_issue_from_invalid_archive() {
        let error = ArchiveError::InvalidArchive("bad header".into());
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
        assert!(issue.message.contains("Invalid archive"));
    }

    #[test]
    fn test_verification_issue_from_security_violation() {
        let error = ArchiveError::SecurityViolation {
            reason: "encrypted".into(),
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::SecurityPolicy);
        assert!(issue.message.contains("Security violation"));
    }

    #[test]
    fn test_security_violation_fails_security_status() {
        let error = ArchiveError::SecurityViolation {
            reason: "symlinks not allowed".into(),
        };
        let report = report_with(vec![VerificationIssue::from_error(&error, None)]);
        assert_eq!(report.status(), VerificationStatus::Fail);
        assert_eq!(report.security_status(), CheckStatus::Fail);
    }

    #[test]
    fn test_is_security_classification() {
        let non_security: Vec<_> = IssueCategory::ALL
            .iter()
            .copied()
            .filter(|c| !c.is_security())
            .collect();
        assert_eq!(
            non_security,
            [
                IssueCategory::InvalidArchive,
                IssueCategory::SuspiciousPath,
                IssueCategory::ExecutableFile
            ]
        );
    }

    #[test]
    fn test_verification_issue_from_source_not_found() {
        let error = ArchiveError::SourceNotFound {
            path: PathBuf::from("/missing"),
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
        assert!(issue.message.contains("Source not found"));
    }

    #[test]
    fn test_verification_issue_from_source_not_accessible() {
        let error = ArchiveError::SourceNotAccessible {
            path: PathBuf::from("/restricted"),
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
        assert!(issue.message.contains("Source not accessible"));
    }

    #[test]
    fn test_verification_issue_from_output_exists() {
        let error = ArchiveError::OutputExists {
            path: PathBuf::from("out/"),
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::Medium);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
        assert!(issue.message.contains("Output already exists"));
    }

    #[test]
    fn test_verification_issue_from_invalid_compression_level() {
        let error = ArchiveError::InvalidCompressionLevel { level: 0 };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::Medium);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
        assert!(issue.message.contains("Invalid compression level"));
    }

    #[test]
    fn test_verification_issue_from_unknown_format() {
        let error = ArchiveError::UnknownFormat {
            path: PathBuf::from("archive.rar"),
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
        assert!(issue.message.contains("Unknown format"));
    }

    #[test]
    fn test_verification_issue_from_invalid_configuration() {
        let error = ArchiveError::InvalidConfiguration {
            reason: "bad config".into(),
        };
        let issue = VerificationIssue::from_error(&error, None);
        assert_eq!(issue.severity, IssueSeverity::High);
        assert_eq!(issue.category, IssueCategory::InvalidArchive);
        assert!(issue.message.contains("Invalid configuration"));
    }

    #[test]
    fn test_verification_report_issues_by_severity() {
        let report = report_with(vec![
            issue(IssueSeverity::Critical, IssueCategory::PathTraversal),
            issue(IssueSeverity::Low, IssueCategory::ExecutableFile),
        ]);

        assert_eq!(report.issues_by_severity(IssueSeverity::Critical).len(), 1);
        assert_eq!(report.issues_by_severity(IssueSeverity::Low).len(), 1);
        assert_eq!(report.status(), VerificationStatus::Fail);
    }
}
